export class Ship {
  #id;
  #startX = -1;
  #startY = -1;
  #isHorizontal = true;
  #length;
  #hitCounter = 0;

  constructor(id, length) {
    this.#id = id;
    this.#length = length;
  }

  getID() {
    return this.#id;
  }

  getLength() {
    return this.#length;
  }

  setProperties(startX, startY, isHorizontal = true) {
    this.#startX = startX;
    this.#startY = startY;
    this.#isHorizontal = isHorizontal;
  }

  getProperties() {
    return {
      id: this.#id,
      startX: this.#startX,
      startY: this.#startY,
      isHorizontal: this.#isHorizontal,
      length: this.#length,
      hasSunk: this.hasSunk(),
    };
  }

  hit() {
    if (this.#hitCounter < this.#length) ++this.#hitCounter;
  }

  getHits() {
    return this.#hitCounter;
  }

  hasSunk() {
    return this.#hitCounter >= this.#length;
  }
}
